 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find colored rectangular frames by connected components.
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
            boxes.append((color, min(rs), max(rs), min(cs), max(cs)))
    # A frame is a rectangle whose entire perimeter is its color. The patterned
    # frame supplies its interior bitmap to otherwise-empty frames of same size.
    frames = []
    for color, r0, r1, c0, c1 in boxes:
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        if all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1)):
            pat = [[grid[r][c] != 0 for c in range(c0+1,c1)] for r in range(r0+1,r1)]
            frames.append((color,r0,r1,c0,c1,pat))
    source = next((f for f in frames if any(any(row) for row in f[5])), None)
    out = [row[:] for row in grid]
    if source:
        _, sr0,sr1,sc0,sc1,pat = source
        for color,r0,r1,c0,c1,p in frames:
            if (r0,r1,c0,c1) == (sr0,sr1,sc0,sc1):
                continue
            if (r1-r0,c1-c0) == (sr1-sr0,sc1-sc0):
                for y in range(len(pat)):
                    for x in range(len(pat[0])):
                        if pat[y][x]: out[r0+1+y][c0+1+x] = color
    return out
